export const CELL_UNIT_OF_LIFE = [
  // ---- MCQ ----
  { id: 'cell-1', type: 'mcq', question: 'The Cell Theory, stating that all living organisms are composed of cells, was significantly expanded by Rudolf Virchow to include the idea that:', options: ['Cells arise only from pre-existing cells', 'Cells can arise spontaneously from non-living matter', 'Only plant cells can divide', 'Cells have no relationship to heredity'], correctIndex: 0, explanation: "Virchow's contribution — 'omnis cellula-e cellula' — states that new cells arise only from pre-existing cells.", difficulty: 'easy' },
  { id: 'cell-2', type: 'mcq', question: 'Cell theory was originally proposed by:', options: ['Robert Hooke alone', 'Schleiden and Schwann', 'Robert Brown', 'Camillo Golgi'], correctIndex: 1, explanation: "M. Schleiden (botanist) and T. Schwann (zoologist) jointly proposed the cell theory in 1838-39.", difficulty: 'easy' },
  { id: 'cell-3', type: 'mcq', question: 'The scientist who first observed and named "cells" while examining cork under a microscope was:', options: ['Robert Brown', 'Robert Hooke', 'Rudolf Virchow', 'Camillo Golgi'], correctIndex: 1, explanation: 'Robert Hooke observed dead cork cells in 1665 and coined the term "cell".', difficulty: 'easy' },
  { id: 'cell-4', type: 'mcq', question: 'The nucleus of the cell was first described by:', options: ['Robert Hooke', 'Robert Brown', 'Purkinje', 'Rudolf Virchow'], correctIndex: 1, explanation: 'Robert Brown first described the cell nucleus in 1831.', difficulty: 'easy' },
  { id: 'cell-5', type: 'mcq', question: 'The fluid content inside a living cell was named "protoplasm" by:', options: ['Purkinje', 'Robert Hooke', 'Schwann', 'Virchow'], correctIndex: 0, explanation: 'Purkinje coined the term "protoplasm" for the fluid substance of the cell.', difficulty: 'medium' },
  { id: 'cell-6', type: 'mcq', question: 'A defining feature that distinguishes a prokaryotic cell from a eukaryotic cell is:', options: ['Absence of a true, membrane-bound nucleus in prokaryotes', 'Absence of ribosomes in prokaryotes', 'Absence of a cell wall in prokaryotes', 'Absence of DNA in prokaryotes'], correctIndex: 0, explanation: 'Prokaryotes lack a nuclear membrane; their genetic material lies in a nucleoid region rather than within a true nucleus.', difficulty: 'easy' },
  { id: 'cell-7', type: 'mcq', question: 'In a bacterial (prokaryotic) cell, the outermost, loose sticky layer surrounding the cell wall is called the:', options: ['Plasma membrane', 'Glycocalyx', 'Nucleoid', 'Mesosome'], correctIndex: 1, explanation: 'The glycocalyx is the outer, loosely bound layer that may exist as a slime layer or capsule.', difficulty: 'medium' },
  { id: 'cell-8', type: 'mcq', question: 'Mesosomes, found in prokaryotic cells, are best described as:', options: ['Membrane-bound organelles similar to mitochondria', 'Extensions/infoldings of the plasma membrane, aiding respiration and DNA replication', 'Structures involved only in photosynthesis', 'Storage vacuoles for water'], correctIndex: 1, explanation: 'Mesosomes are plasma membrane infoldings that increase surface area for respiratory enzymes and help in DNA replication/cell division.', difficulty: 'medium' },
  { id: 'cell-9', type: 'mcq', question: 'Ribosomes in prokaryotic cells are of which sedimentation coefficient type?', options: ['80S', '70S', '60S', '40S'], correctIndex: 1, explanation: 'Prokaryotic ribosomes are 70S, composed of 50S and 30S subunits.', difficulty: 'easy' },
  { id: 'cell-10', type: 'mcq', question: 'Ribosomes in eukaryotic cells (in the cytoplasm) are of which type?', options: ['70S', '80S', '50S', '30S'], correctIndex: 1, explanation: 'Eukaryotic cytoplasmic ribosomes are 80S, made of 60S and 40S subunits.', difficulty: 'easy' },
  { id: 'cell-11', type: 'mcq', question: 'The main chemical component of most bacterial cell walls is:', options: ['Cellulose', 'Peptidoglycan (murein)', 'Chitin', 'Pectin'], correctIndex: 1, explanation: 'Bacterial cell walls are primarily composed of peptidoglycan, a polymer of sugars and amino acids.', difficulty: 'medium' },
  { id: 'cell-12', type: 'mcq', question: 'The main chemical component of a typical plant cell wall is:', options: ['Peptidoglycan', 'Chitin', 'Cellulose', 'Keratin'], correctIndex: 2, explanation: 'Plant cell walls are primarily built from cellulose fibres.', difficulty: 'easy' },
  { id: 'cell-13', type: 'mcq', question: 'The Fluid Mosaic Model of the plasma membrane was proposed by:', options: ['Singer and Nicolson', 'Watson and Crick', 'Schleiden and Schwann', 'Robertson'], correctIndex: 0, explanation: 'Singer and Nicolson proposed the fluid mosaic model in 1972, describing the membrane as a fluid lipid bilayer with embedded proteins.', difficulty: 'medium' },
  { id: 'cell-14', type: 'mcq', question: 'The plasma membrane is described as "selectively permeable" because it:', options: ['Allows all substances to pass through freely', 'Allows only certain substances to pass through in a regulated manner', 'Blocks the passage of all substances completely', 'Is completely impermeable to water'], correctIndex: 1, explanation: 'Selective permeability means the membrane regulates which molecules can cross and to what extent.', difficulty: 'easy' },
  { id: 'cell-15', type: 'mcq', question: 'Rough Endoplasmic Reticulum (RER) appears "rough" under the microscope because of the presence of:', options: ['Attached ribosomes', 'Chlorophyll pigments', 'Cellulose deposits', 'Lysosomal enzymes'], correctIndex: 0, explanation: 'Ribosomes studded on the RER surface give it a rough appearance and enable protein synthesis directly onto the membrane.', difficulty: 'easy' },
  { id: 'cell-16', type: 'mcq', question: 'Smooth Endoplasmic Reticulum (SER) is primarily associated with:', options: ['Protein synthesis', 'Lipid/steroid synthesis', 'ATP production', 'Chromosome condensation'], correctIndex: 1, explanation: 'SER lacks ribosomes and is mainly involved in lipid and steroid hormone synthesis.', difficulty: 'easy' },
  { id: 'cell-17', type: 'mcq', question: 'The Golgi apparatus was first described by:', options: ['Robert Hooke', 'Camillo Golgi', 'Rudolf Virchow', 'Purkinje'], correctIndex: 1, explanation: 'Camillo Golgi first described this organelle, which now bears his name.', difficulty: 'medium' },
  { id: 'cell-18', type: 'mcq', question: 'A primary function of the Golgi apparatus is:', options: ['DNA replication', 'Packaging, modification, and secretion of materials, including glycosylation of proteins', 'Cellular respiration', 'Photosynthesis'], correctIndex: 1, explanation: 'The Golgi packages and chemically modifies (e.g., glycosylates) materials received from the ER before dispatch.', difficulty: 'medium' },
  { id: 'cell-19', type: 'mcq', question: 'Lysosomes are often referred to as the "suicide bags" of the cell because they:', options: ['Produce large amounts of ATP', 'Contain hydrolytic enzymes capable of digesting the cell\'s own contents if released', 'Store starch for the cell', 'Synthesise all cellular proteins'], correctIndex: 1, explanation: 'If a lysosome ruptures, its hydrolytic enzymes can digest the cell itself, hence the nickname "suicide bags".', difficulty: 'medium' },
  { id: 'cell-20', type: 'mcq', question: 'A large, membrane-bound vacuole occupying most of the volume in a mature plant cell is bound by a membrane called the:', options: ['Sarcolemma', 'Tonoplast', 'Plasmalemma only', 'Nuclear envelope'], correctIndex: 1, explanation: 'The tonoplast is the specific membrane surrounding the plant cell vacuole.', difficulty: 'medium' },
  { id: 'cell-21', type: 'mcq', question: 'Mitochondria are often called the "powerhouse of the cell" because they:', options: ['Store genetic information', 'Are the primary site of aerobic respiration and ATP synthesis', 'Synthesise lipids', 'Package and secrete proteins'], correctIndex: 1, explanation: 'Mitochondria carry out oxidative phosphorylation, generating most of the cell\'s ATP.', difficulty: 'easy' },
  { id: 'cell-22', type: 'mcq', question: 'Mitochondria possess their own DNA and ribosomes of which type?', options: ['80S ribosomes and linear DNA', '70S ribosomes and circular DNA', '60S ribosomes only', 'No DNA or ribosomes of their own'], correctIndex: 1, explanation: "Mitochondria have circular DNA and 70S ribosomes, consistent with the endosymbiotic theory of their origin.", difficulty: 'medium' },
  { id: 'cell-23', type: 'mcq', question: 'The infoldings of the inner mitochondrial membrane, which increase surface area for respiratory reactions, are called:', options: ['Grana', 'Cristae', 'Thylakoids', 'Cisternae'], correctIndex: 1, explanation: 'Cristae are folds of the inner mitochondrial membrane that increase the surface area available for the electron transport chain.', difficulty: 'easy' },
  { id: 'cell-24', type: 'mcq', question: 'Plastids that contain chlorophyll and are the site of photosynthesis are called:', options: ['Leucoplasts', 'Chromoplasts', 'Chloroplasts', 'Elaioplasts'], correctIndex: 2, explanation: 'Chloroplasts contain chlorophyll and carry out photosynthesis.', difficulty: 'easy' },
  { id: 'cell-25', type: 'mcq', question: 'Colourless plastids that mainly store starches, oils, and proteins are called:', options: ['Chloroplasts', 'Chromoplasts', 'Leucoplasts', 'Elaioplasts only'], correctIndex: 2, explanation: 'Leucoplasts are colourless plastids specialised for storage of starch (amyloplasts), oils (elaioplasts), or proteins (aleuroplasts).', difficulty: 'medium' },
  { id: 'cell-26', type: 'mcq', question: 'Plastids that impart yellow, orange, or red colours to plant parts (like ripe tomatoes) are called:', options: ['Chloroplasts', 'Chromoplasts', 'Leucoplasts', 'Proplastids only'], correctIndex: 1, explanation: 'Chromoplasts contain carotenoid pigments responsible for yellow/orange/red colouration.', difficulty: 'medium' },
  { id: 'cell-27', type: 'mcq', question: 'Within a chloroplast, the stacked, disc-shaped membranous structures are called:', options: ['Cristae', 'Grana (composed of thylakoids)', 'Cisternae', 'Nucleoids'], correctIndex: 1, explanation: 'Thylakoids stack to form grana within the chloroplast stroma, housing the light reaction machinery.', difficulty: 'medium' },
  { id: 'cell-28', type: 'mcq', question: 'Ribosomes are composed of:', options: ['Only protein', 'Only RNA', 'Ribosomal RNA (rRNA) and proteins', 'DNA and lipids'], correctIndex: 2, explanation: 'Ribosomes are ribonucleoprotein particles made of rRNA and structural proteins.', difficulty: 'easy' },
  { id: 'cell-29', type: 'mcq', question: 'The cytoskeleton, which provides mechanical support and helps in cell motility, is composed of a network of:', options: ['Only DNA strands', 'Microtubules, microfilaments, and intermediate filaments', 'Only ribosomes', 'Only mitochondria'], correctIndex: 1, explanation: 'The cytoskeleton is a filamentous network of microtubules, microfilaments, and intermediate filaments.', difficulty: 'medium' },
  { id: 'cell-30', type: 'mcq', question: 'The internal structure of cilia and flagella typically shows a characteristic arrangement of microtubules known as:', options: ['6+2 arrangement', '9+2 arrangement', '9+0 arrangement only', '2+9 arrangement'], correctIndex: 1, explanation: 'The axoneme of cilia/flagella shows a 9+2 arrangement — nine peripheral doublets surrounding two central microtubules.', difficulty: 'medium' },
  { id: 'cell-31', type: 'mcq', question: 'The basal body, which anchors a cilium or flagellum to the cell and resembles a centriole, shows which microtubule arrangement?', options: ['9+2', '9+0', '6+2', '2+2'], correctIndex: 1, explanation: 'Basal bodies (like centrioles) show a 9+0 arrangement — nine peripheral triplets and no central pair.', difficulty: 'hard' },
  { id: 'cell-32', type: 'mcq', question: 'Centrioles are primarily associated with the formation of:', options: ['The nuclear envelope', 'Spindle fibres during cell division and basal bodies of cilia/flagella', 'The cell wall', 'Lysosomal enzymes'], correctIndex: 1, explanation: 'Centrioles organise spindle fibre formation during division and also form the basal bodies of cilia and flagella.', difficulty: 'medium' },
  { id: 'cell-33', type: 'mcq', question: 'The nuclear envelope is perforated by numerous nuclear pores, which primarily function to:', options: ['Prevent all molecular movement between nucleus and cytoplasm', 'Regulate the movement of RNA and proteins between the nucleus and cytoplasm', 'Produce ATP', 'Store lipid droplets'], correctIndex: 1, explanation: 'Nuclear pores allow controlled bidirectional transport of macromolecules (like mRNA out, proteins in).', difficulty: 'medium' },
  { id: 'cell-34', type: 'mcq', question: 'Chromatin, found within the nucleus, is composed of:', options: ['DNA and associated histone proteins', 'Only RNA', 'Only lipids', 'Cellulose fibres'], correctIndex: 0, explanation: 'Chromatin is the complex of DNA wound around histone proteins, forming the physical basis of chromosomes.', difficulty: 'easy' },
  { id: 'cell-35', type: 'mcq', question: 'The nucleolus, found within the nucleus, is primarily the site of:', options: ['DNA replication', 'Ribosomal RNA (rRNA) synthesis and ribosome assembly', 'Protein folding', 'Fat storage'], correctIndex: 1, explanation: 'The nucleolus is a dense region specialised for rRNA synthesis and initial ribosome subunit assembly.', difficulty: 'medium' },
  { id: 'cell-36', type: 'mcq', question: 'Chromatin condenses into visible, distinct structures called chromosomes primarily during:', options: ['Interphase', 'Cell division', 'Only in dead cells', 'Only in prokaryotic cells'], correctIndex: 1, explanation: 'Loosely dispersed chromatin condenses into compact chromosomes during cell division for proper segregation.', difficulty: 'easy' },
  { id: 'cell-37', type: 'mcq', question: 'The layer of a mature plant cell wall that is shared between two adjacent cells, holding them together, is the:', options: ['Primary wall', 'Secondary wall', 'Middle lamella', 'Tonoplast'], correctIndex: 2, explanation: 'The middle lamella, rich in calcium pectate, cements together the walls of adjacent plant cells.', difficulty: 'medium' },
  { id: 'cell-38', type: 'mcq', question: 'Cytoplasmic connections that pass through the walls of adjacent plant cells, allowing direct communication between them, are called:', options: ['Mesosomes', 'Plasmodesmata', 'Pili', 'Fimbriae'], correctIndex: 1, explanation: 'Plasmodesmata are channels through plant cell walls connecting the cytoplasm of neighbouring cells.', difficulty: 'medium' },
  { id: 'cell-39', type: 'mcq', question: 'The general size range of most prokaryotic cells is:', options: ['0.1–0.5 micrometres', '1–10 micrometres', '100–500 micrometres', '1000 micrometres or larger'], correctIndex: 1, explanation: 'Most bacterial cells range roughly between 1 and 10 micrometres in size.', difficulty: 'medium' },
  { id: 'cell-40', type: 'mcq', question: 'Bacterial flagella differ from eukaryotic flagella in that bacterial flagella:', options: ['Have the same 9+2 microtubule arrangement', 'Lack the typical membrane covering and microtubule (9+2) organisation seen in eukaryotic flagella', 'Are always longer than eukaryotic flagella', 'Cannot be used for movement'], correctIndex: 1, explanation: 'Bacterial flagella are structurally simpler, made of the protein flagellin, without a membrane covering or the eukaryotic 9+2 microtubule pattern.', difficulty: 'hard' },
  { id: 'cell-41', type: 'mcq', question: 'Short, hair-like structures on the surface of some bacteria that help in attachment to surfaces or other cells are called:', options: ['Flagella', 'Pili/Fimbriae', 'Mesosomes', 'Ribosomes'], correctIndex: 1, explanation: 'Pili (or fimbriae) are surface appendages aiding bacterial attachment and, in some cases, conjugation.', difficulty: 'medium' },
  { id: 'cell-42', type: 'mcq', question: 'Reserve/storage materials found in the cytoplasm of prokaryotic cells, which are NOT bound by any membrane, are called:', options: ['Membrane-bound organelles', 'Inclusion bodies', 'Nuclear envelopes', 'Golgi vesicles'], correctIndex: 1, explanation: 'Prokaryotic inclusion bodies (e.g., glycogen granules, gas vacuoles) store reserve materials but lack a surrounding membrane.', difficulty: 'medium' },
  { id: 'cell-43', type: 'mcq', question: 'Under unfavourable conditions, some bacteria form a highly resistant, dormant structure called a(n):', options: ['Mesosome', 'Endospore', 'Ribosome', 'Nucleoid'], correctIndex: 1, explanation: 'Endospores are dormant, thick-walled structures that allow certain bacteria to survive harsh conditions.', difficulty: 'medium' },
  { id: 'cell-44', type: 'mcq', question: 'Peroxisomes are membrane-bound organelles primarily involved in:', options: ['Protein synthesis', 'Oxidative reactions that produce and break down hydrogen peroxide (H2O2)', 'DNA replication', 'ATP synthesis via the electron transport chain'], correctIndex: 1, explanation: 'Peroxisomes carry out oxidative reactions producing H2O2 and contain catalase to break it down safely.', difficulty: 'medium' },
  { id: 'cell-45', type: 'mcq', question: 'Glyoxysomes, found in certain plant cells (like germinating fatty seeds), are specialised organelles primarily involved in:', options: ['Photosynthesis', 'Conversion of stored fats into carbohydrates', 'DNA repair', 'Cellulose synthesis'], correctIndex: 1, explanation: 'Glyoxysomes house enzymes of the glyoxylate cycle, helping convert fat reserves into usable sugars in germinating seeds.', difficulty: 'hard' },
  { id: 'cell-46', type: 'mcq', question: 'Which of the following structures is generally present in a typical plant cell but absent in a typical animal cell?', options: ['Mitochondria', 'Ribosomes', 'A large central vacuole and cell wall', 'Plasma membrane'], correctIndex: 2, explanation: 'A prominent central vacuole and a rigid cell wall are characteristic plant cell features, generally absent in animal cells.', difficulty: 'easy' },
  { id: 'cell-47', type: 'mcq', question: 'Centrioles are typically present in animal cells but are usually absent in the cells of:', options: ['Bacteria only', 'Most flowering (higher) plants', 'All eukaryotes without exception', 'Fungi only'], correctIndex: 1, explanation: 'Most higher plant cells lack centrioles, unlike typical animal cells.', difficulty: 'medium' },
  { id: 'cell-48', type: 'mcq', question: 'When a plant cell placed in a hypertonic solution loses water and its cytoplasm shrinks away from the cell wall, this phenomenon is called:', options: ['Osmosis', 'Plasmolysis', 'Diffusion', 'Active transport'], correctIndex: 1, explanation: 'Plasmolysis is the shrinkage of the protoplast away from the cell wall due to water loss in a hypertonic environment.', difficulty: 'medium' },
  { id: 'cell-49', type: 'mcq', question: 'The movement of molecules across a membrane against their concentration gradient, requiring energy input, is called:', options: ['Simple diffusion', 'Facilitated diffusion', 'Active transport', 'Osmosis'], correctIndex: 2, explanation: 'Active transport moves substances against their gradient and requires ATP.', difficulty: 'easy' },
  { id: 'cell-50', type: 'mcq', question: 'Small, circular, extrachromosomal DNA molecules found in many bacteria, often carrying genes like antibiotic resistance, are called:', options: ['Nucleoids', 'Plasmids', 'Ribosomes', 'Mesosomes'], correctIndex: 1, explanation: 'Plasmids are self-replicating extrachromosomal DNA elements, frequently carrying resistance or other accessory genes.', difficulty: 'easy' },

  // ---- Assertion-Reason ----
  { id: 'cell-ar-1', type: 'assertion-reason', question: 'Assertion (A): All living organisms are composed of cells.\nReason (R): New cells arise only from pre-existing cells, according to modern cell theory.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 1, explanation: 'Both statements are core, true tenets of cell theory, but R (about cell origin) does not directly explain WHY all organisms are cellular — they are two separate, related principles.', difficulty: 'medium' },
  { id: 'cell-ar-2', type: 'assertion-reason', question: 'Assertion (A): Prokaryotic cells lack a true, membrane-bound nucleus.\nReason (R): Their genetic material lies free in the cytoplasm within a region called the nucleoid.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'DNA lying unbound in the nucleoid region, without a surrounding nuclear membrane, is exactly why prokaryotes lack a true nucleus.', difficulty: 'medium' },
  { id: 'cell-ar-3', type: 'assertion-reason', question: 'Assertion (A): Mesosomes in bacteria are functionally equivalent to mitochondria in eukaryotic cells.\nReason (R): Mesosomes are simple infoldings of the plasma membrane, not distinct membrane-bound organelles like mitochondria.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Mesosomes are NOT truly equivalent to mitochondria (A is false, an oversimplification); R correctly clarifies their actual, simpler structural nature.', difficulty: 'hard' },
  { id: 'cell-ar-4', type: 'assertion-reason', question: "Assertion (A): The plasma membrane is described using the fluid mosaic model.\nReason (R): Proteins are embedded within or attached to a fluid phospholipid bilayer, both of which can move laterally.", options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "The lateral mobility of proteins within a fluid lipid bilayer is exactly what the 'fluid mosaic' description captures.", difficulty: 'medium' },
  { id: 'cell-ar-5', type: 'assertion-reason', question: 'Assertion (A): Rough Endoplasmic Reticulum is directly involved in lipid synthesis.\nReason (R): RER is studded with ribosomes, which are the site of protein synthesis.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'RER is mainly associated with PROTEIN (not lipid) synthesis — lipid synthesis is the role of SER — so A is false; R correctly describes RER\'s actual ribosome-studded structure.', difficulty: 'medium' },
  { id: 'cell-ar-6', type: 'assertion-reason', question: 'Assertion (A): Lysosomes are called "suicide bags" of the cell.\nReason (R): They contain powerful hydrolytic enzymes that can digest cellular components if released into the cytoplasm.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'The potential for self-digestion if enzymes are released is exactly why lysosomes earned this nickname.', difficulty: 'medium' },
  { id: 'cell-ar-7', type: 'assertion-reason', question: 'Assertion (A): Mitochondria are believed to have originated from free-living prokaryotes, according to the endosymbiotic theory.\nReason (R): Mitochondria possess their own circular DNA and 70S ribosomes, similar to bacteria.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'These bacteria-like features (circular DNA, 70S ribosomes) are exactly what support the endosymbiotic origin theory.', difficulty: 'medium' },
  { id: 'cell-ar-8', type: 'assertion-reason', question: 'Assertion (A): Chloroplasts and mitochondria are both surrounded by a single membrane.\nReason (R): Both organelles are believed to have originated from free-living prokaryotes through endosymbiosis.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Both organelles actually have a DOUBLE membrane, not a single one (A is false); R is true and reflects the widely accepted endosymbiotic theory for their origin.', difficulty: 'medium' },
  { id: 'cell-ar-9', type: 'assertion-reason', question: 'Assertion (A): Ribosomes are considered non-membranous cell organelles.\nReason (R): Ribosomes are composed of rRNA and protein, without any surrounding lipid membrane.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Lacking a membrane covering, being just rRNA and protein, is exactly why ribosomes are classified as non-membranous organelles.', difficulty: 'medium' },
  { id: 'cell-ar-10', type: 'assertion-reason', question: 'Assertion (A): Cilia and flagella both show a 9+2 arrangement of microtubules in their core axoneme.\nReason (R): This arrangement provides the structural basis for their characteristic bending, whip-like movements.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "The 9+2 microtubule arrangement, along with motor proteins like dynein, is exactly what enables their characteristic movement.", difficulty: 'medium' },
  { id: 'cell-ar-11', type: 'assertion-reason', question: 'Assertion (A): Centrioles are present in the cells of most flowering plants.\nReason (R): Most flowering plant cells lack centrioles, though spindle fibre formation can still occur during division.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Most higher plant cells actually LACK centrioles (A is false); R correctly states this and notes spindle formation can occur without them.', difficulty: 'medium' },
  { id: 'cell-ar-12', type: 'assertion-reason', question: 'Assertion (A): The nucleolus is a membrane-bound organelle within the nucleus.\nReason (R): The nucleolus is the site of ribosomal RNA synthesis and ribosome subunit assembly.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'The nucleolus is actually a non-membrane-bound, dense region within the nucleus (A is false); R correctly describes its function.', difficulty: 'medium' },
  { id: 'cell-ar-13', type: 'assertion-reason', question: 'Assertion (A): Chromatin condenses into chromosomes only during cell division.\nReason (R): Condensation into compact, visible chromosome structures aids in accurate segregation of genetic material.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Facilitating accurate segregation during division is exactly why chromatin condenses into chromosomes at that time.', difficulty: 'medium' },
  { id: 'cell-ar-14', type: 'assertion-reason', question: 'Assertion (A): Plasmodesmata allow direct communication between adjacent plant cells.\nReason (R): They are cytoplasmic channels that pass through the cell walls connecting neighbouring cells.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'These direct cytoplasmic channels through the cell wall are exactly what allow inter-cellular communication in plants.', difficulty: 'medium' },
  { id: 'cell-ar-15', type: 'assertion-reason', question: 'Assertion (A): Endospores allow certain bacteria to survive extremely harsh environmental conditions.\nReason (R): Endospores are metabolically highly active, rapidly growing structures.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 2, explanation: 'A is true, but R is false — endospores are actually metabolically DORMANT (not active), which is exactly what allows them to survive harsh conditions.', difficulty: 'medium' },
  { id: 'cell-ar-16', type: 'assertion-reason', question: 'Assertion (A): Peroxisomes contain the enzyme catalase.\nReason (R): Catalase breaks down hydrogen peroxide, a potentially toxic by-product of oxidative reactions occurring in peroxisomes.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "Neutralising the toxic H2O2 produced by peroxisomal reactions is exactly why catalase is present there.", difficulty: 'medium' },
  { id: 'cell-ar-17', type: 'assertion-reason', question: 'Assertion (A): A plant cell placed in a hypotonic solution will undergo plasmolysis.\nReason (R): In a hypotonic solution, water moves into the cell, causing it to swell rather than shrink.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Plasmolysis actually occurs in a HYPERTONIC (not hypotonic) solution (A is false); R correctly describes what happens in a hypotonic solution instead (swelling, not shrinking).', difficulty: 'medium' },
  { id: 'cell-ar-18', type: 'assertion-reason', question: 'Assertion (A): Active transport of molecules across a membrane requires energy input, typically from ATP.\nReason (R): Active transport moves molecules against their concentration gradient.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Moving molecules against their gradient is energetically unfavourable, which is exactly why active transport requires ATP.', difficulty: 'medium' },
  { id: 'cell-ar-19', type: 'assertion-reason', question: 'Assertion (A): Plasmids in bacteria are essential for the survival of the bacterium under all conditions.\nReason (R): Plasmids are extrachromosomal, self-replicating DNA elements that often carry non-essential but sometimes advantageous genes (e.g., antibiotic resistance).', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Plasmids are generally NOT essential for basic survival (A is false) — they carry accessory, often advantageous (but non-essential) genes, as R correctly explains.', difficulty: 'medium' },
  { id: 'cell-ar-20', type: 'assertion-reason', question: 'Assertion (A): Glyoxysomes are found in animal cells and are involved in muscle contraction.\nReason (R): Glyoxysomes are specialised plant organelles that help convert stored fats into carbohydrates during seed germination.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Glyoxysomes are found in PLANT cells (not animal cells) and are unrelated to muscle contraction (A is false); R correctly describes their actual role.', difficulty: 'hard' },

  // ---- Statement-based ----
  { id: 'cell-st-1', type: 'statement', question: 'Statement I: According to cell theory, all cells arise from pre-existing cells.\nStatement II: Cell theory also states that the cell is the basic structural and functional unit of life.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly represent the core tenets of modern cell theory.', difficulty: 'easy' },
  { id: 'cell-st-2', type: 'statement', question: 'Statement I: Prokaryotic ribosomes are 80S, while eukaryotic cytoplasmic ribosomes are 70S.\nStatement II: Ribosomes are composed of rRNA and protein regardless of cell type.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is reversed and incorrect — prokaryotic ribosomes are 70S, eukaryotic are 80S; Statement II correctly describes ribosome composition in general.', difficulty: 'medium' },
  { id: 'cell-st-3', type: 'statement', question: 'Statement I: The bacterial cell wall is mainly composed of cellulose.\nStatement II: The plant cell wall is mainly composed of cellulose.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — bacterial walls are mainly peptidoglycan, not cellulose; Statement II correctly describes plant cell walls.', difficulty: 'medium' },
  { id: 'cell-st-4', type: 'statement', question: 'Statement I: The fluid mosaic model describes the plasma membrane as a rigid, static structure.\nStatement II: According to this model, membrane proteins and lipids can move laterally within the bilayer.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — the model emphasises fluidity, not rigidity; Statement II correctly describes the lateral mobility central to the model.', difficulty: 'medium' },
  { id: 'cell-st-5', type: 'statement', question: 'Statement I: SER is associated with lipid and steroid synthesis.\nStatement II: RER is studded with ribosomes and is primarily involved in protein synthesis.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly distinguish the roles of SER and RER.', difficulty: 'easy' },
  { id: 'cell-st-6', type: 'statement', question: 'Statement I: The Golgi apparatus is involved in packaging and secretion of cellular products.\nStatement II: The Golgi apparatus is the primary site of ATP synthesis in the cell.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — ATP synthesis primarily occurs in mitochondria, not the Golgi apparatus.', difficulty: 'medium' },
  { id: 'cell-st-7', type: 'statement', question: 'Statement I: Lysosomes contain hydrolytic enzymes active at an acidic pH.\nStatement II: Lysosomes are involved in intracellular digestion of materials.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements accurately describe key features and functions of lysosomes.', difficulty: 'medium' },
  { id: 'cell-st-8', type: 'statement', question: 'Statement I: Mitochondria have a single, smooth outer membrane and no inner membrane.\nStatement II: Mitochondria have a double membrane, with the inner membrane forming folds called cristae.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — mitochondria have a double membrane, not just a single one; Statement II correctly describes their actual structure.', difficulty: 'medium' },
  { id: 'cell-st-9', type: 'statement', question: 'Statement I: Chloroplasts, chromoplasts, and leucoplasts are all types of plastids.\nStatement II: Leucoplasts are typically green due to chlorophyll content.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — leucoplasts are colourless (lacking pigments), unlike chloroplasts.', difficulty: 'medium' },
  { id: 'cell-st-10', type: 'statement', question: 'Statement I: The cytoskeleton is made up of microtubules, microfilaments, and intermediate filaments.\nStatement II: The cytoskeleton has no role in cell shape or movement.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — the cytoskeleton is central to maintaining cell shape and enabling movement/transport.', difficulty: 'medium' },
  { id: 'cell-st-11', type: 'statement', question: 'Statement I: Cilia are generally longer than flagella and present in much greater numbers per cell.\nStatement II: Flagella are generally longer than cilia and present in fewer numbers per cell.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect (roles are reversed); Statement II correctly describes the typical size/number relationship between flagella and cilia.', difficulty: 'medium' },
  { id: 'cell-st-12', type: 'statement', question: 'Statement I: Centrioles are found at the base of cilia and flagella as basal bodies.\nStatement II: Centrioles also play a role in organising spindle fibres during cell division.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe key roles of centrioles.', difficulty: 'medium' },
  { id: 'cell-st-13', type: 'statement', question: 'Statement I: The nuclear envelope is a single continuous membrane with no pores.\nStatement II: The nuclear envelope is a double membrane structure perforated by nuclear pores.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — the nuclear envelope is double-membraned and has pores; Statement II correctly describes its actual structure.', difficulty: 'medium' },
  { id: 'cell-st-14', type: 'statement', question: 'Statement I: Chromatin is composed of DNA wound around histone proteins.\nStatement II: Chromatin condenses into chromosomes specifically during cell division.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe chromatin structure and its condensation behaviour.', difficulty: 'easy' },
  { id: 'cell-st-15', type: 'statement', question: 'Statement I: Prokaryotic cells generally range from 1 to 10 micrometres in size.\nStatement II: Eukaryotic cells are generally smaller than prokaryotic cells.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — eukaryotic cells are generally LARGER (5–100 micrometres), not smaller, than prokaryotic cells.', difficulty: 'medium' },
  { id: 'cell-st-16', type: 'statement', question: 'Statement I: Bacterial flagella have the same 9+2 microtubule structure as eukaryotic flagella.\nStatement II: Bacterial flagella are made of the protein flagellin and lack a membrane covering.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — bacterial flagella structurally differ significantly from eukaryotic ones; Statement II correctly describes bacterial flagella.', difficulty: 'medium' },
  { id: 'cell-st-17', type: 'statement', question: 'Statement I: Inclusion bodies in prokaryotic cells are bound by a unit membrane, similar to eukaryotic organelles.\nStatement II: Inclusion bodies store reserve materials like glycogen, lipids, and gas vesicles.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — prokaryotic inclusion bodies are NOT membrane-bound; Statement II correctly describes what they store.', difficulty: 'medium' },
  { id: 'cell-st-18', type: 'statement', question: 'Statement I: A plant cell in a hypertonic solution will undergo plasmolysis.\nStatement II: A plant cell in a hypotonic solution will typically swell but not burst, due to the rigid cell wall.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe plant cell behaviour under hypertonic and hypotonic conditions respectively.', difficulty: 'medium' },
  { id: 'cell-st-19', type: 'statement', question: 'Statement I: Simple diffusion requires ATP to move molecules across a membrane.\nStatement II: Active transport requires ATP to move molecules against their concentration gradient.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — simple diffusion is passive and needs no ATP; Statement II correctly describes active transport.', difficulty: 'medium' },
  { id: 'cell-st-20', type: 'statement', question: 'Statement I: Plasmids are found only in eukaryotic cells.\nStatement II: Plasmids are self-replicating, extrachromosomal DNA molecules commonly found in bacteria.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — plasmids are typically a prokaryotic (bacterial) feature, not eukaryotic; Statement II correctly describes plasmids.', difficulty: 'medium' },

  // ---- "How many of the following are correct" ----
  { id: 'cell-hm-1', type: 'statement', question: 'How many of the following are correctly credited to the scientist named?\nRobert Hooke – observed and named cells, Robert Brown – described the nucleus, Schleiden and Schwann – proposed cell theory, Rudolf Virchow – discovered mitochondria', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three attributions are correct; Virchow is credited with "omnis cellula-e cellula," not the discovery of mitochondria.', difficulty: 'medium' },
  { id: 'cell-hm-2', type: 'statement', question: 'How many of the following are features generally found in a typical prokaryotic cell?\nNucleoid region instead of a true nucleus, 70S ribosomes, Membrane-bound organelles like mitochondria and Golgi apparatus, A cell wall (in most bacteria)', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Nucleoid region, 70S ribosomes, and a cell wall are correct prokaryotic features; membrane-bound organelles like mitochondria and Golgi are absent in prokaryotic cells.', difficulty: 'medium' },
  { id: 'cell-hm-3', type: 'statement', question: 'How many of the following organelles are surrounded by a double membrane?\nMitochondria, Chloroplasts, Nucleus, Lysosomes', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Mitochondria, chloroplasts, and the nucleus all have double membranes; lysosomes have only a single membrane.', difficulty: 'medium' },
  { id: 'cell-hm-4', type: 'statement', question: 'How many of the following are types of plastids?\nChloroplast, Chromoplast, Leucoplast, Peroxisome', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Chloroplast, chromoplast, and leucoplast are the three types of plastids; peroxisomes are unrelated, non-plastid organelles.', difficulty: 'easy' },
  { id: 'cell-hm-5', type: 'statement', question: 'How many of the following structures are part of the cytoskeleton?\nMicrotubules, Microfilaments, Intermediate filaments, Ribosomes', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Microtubules, microfilaments, and intermediate filaments make up the cytoskeleton; ribosomes are unrelated protein-synthesis structures.', difficulty: 'medium' },
  { id: 'cell-hm-6', type: 'statement', question: 'How many of the following show a 9+2 microtubule arrangement?\nCilia, Flagella (eukaryotic), Centrioles, Basal bodies', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Cilia and eukaryotic flagella show the 9+2 arrangement; centrioles and basal bodies instead show a 9+0 arrangement.', difficulty: 'hard' },
  { id: 'cell-hm-7', type: 'statement', question: 'How many of the following are functions correctly associated with the Golgi apparatus?\nGlycosylation of proteins, Packaging of secretory materials, Formation of lysosomes, Aerobic respiration and ATP synthesis', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Glycosylation, packaging, and lysosome formation are all Golgi functions; aerobic respiration/ATP synthesis is a mitochondrial function.', difficulty: 'medium' },
  { id: 'cell-hm-8', type: 'statement', question: 'How many of the following organelles/structures are found in a typical bacterial (prokaryotic) cell?\nRibosomes, Nucleoid, Cell wall, Mitochondria', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Ribosomes, nucleoid, and cell wall are typical prokaryotic features; mitochondria are absent in prokaryotic cells.', difficulty: 'medium' },
  { id: 'cell-hm-9', type: 'statement', question: 'How many of the following are true regarding the plant cell wall?\nIt is mainly composed of cellulose, It includes a middle lamella shared between adjacent cells, It contains plasmodesmata connecting neighbouring cells, It is entirely absent in mature plant cells', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Cellulose composition, middle lamella, and plasmodesmata are all correct; the wall is very much PRESENT (not absent) in mature plant cells.', difficulty: 'medium' },
  { id: 'cell-hm-10', type: 'statement', question: 'How many of the following organelles/structures contain their own DNA?\nMitochondria, Chloroplasts, Nucleus, Golgi apparatus', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Mitochondria, chloroplasts, and the nucleus all contain DNA; the Golgi apparatus does not have its own DNA.', difficulty: 'medium' },
];
